/**
 * 2D illustrated exercise scene (SVG string). Visual language from the
 * 안면마비 재활 prototype (face2d.js): skin gradient, muscle band with fibres,
 * semi-transparent hands, fixing lock, pull arrows and callouts naming the
 * landmark and action. Generalised to the whole face in ELC (face.ts) with
 * measured proportions, expressions, skin stretch and head motion.
 */
import { FACE, MUSCLES, XM, type MuscleShape, type Pt } from '../../rehab/face';
import type { Expr, Scene } from '../../rehab/motion';
import { isFixed, type Contact } from '../../rehab/stretches';
import { fingerHand, lockBadge, palmHand, pressShadow, stretchLines, type Pad, type V } from './hand2d';

export const HAND_COLOR = { A: '#2F80ED', B: '#F2994A' } as const;
export const U = 34;

export interface View2D {
  affectedSide: 'left' | 'right';
  /** Mirror view: the patient's own right appears on the screen's right. */
  mirror: boolean;
  showMuscle: boolean;
  callouts: boolean;
  ghostHands: boolean;
  /** Crop for thumbnails (no callouts, tighter frame). */
  compact?: boolean;
  /** The loupe overlays the top of the healthy side: keep callouts below it. */
  loupe?: boolean;
  /** 3D only: jointed hands (ignored by the 2D renderer). */
  riggedHands?: boolean;
}

type Frame = { s: number; toS: (p: Pt) => V; dir: (d: Pt) => V };

function frame(v: View2D): Frame {
  const s = (v.affectedSide === 'right') === v.mirror ? 1 : -1;
  return {
    s,
    toS: ([x, y]) => [s * (x - XM) * U, -y * U],
    dir: ([x, y]) => {
      const l = Math.hypot(x, y) || 1;
      return [(s * x) / l, -y / l];
    },
  };
}

const f1 = (n: number) => n.toFixed(1);

function smooth(points: V[], closed: boolean): string {
  const n = points.length;
  if (n < 2) return '';
  const get = (i: number) => (closed ? points[(i + n) % n]! : points[Math.max(0, Math.min(n - 1, i))]!);
  let d = `M${f1(points[0]![0])},${f1(points[0]![1])}`;
  const segs = closed ? n : n - 1;
  for (let i = 0; i < segs; i++) {
    const [p0, p1, p2, p3] = [get(i - 1), get(i), get(i + 1), get(i + 2)];
    d += ` C${f1(p1[0] + (p2[0] - p0[0]) / 6)},${f1(p1[1] + (p2[1] - p0[1]) / 6)} ${f1(p2[0] - (p3[0] - p1[0]) / 6)},${f1(p2[1] - (p3[1] - p1[1]) / 6)} ${f1(p2[0])},${f1(p2[1])}`;
  }
  return closed ? `${d}Z` : d;
}

const mirrorPt = ([x, y]: Pt): Pt => [2 * XM - x, y];

// ── Skin deformation (same model as the 3D avatar) ───────────────────────

type Warp = (p: Pt) => Pt;

function makeWarp(scene: Scene): Warp {
  if (scene.mode !== 'stretch' || scene.stretch <= 0) return (p) => p;
  const pulls = scene.hands
    .filter((h) => !isFixed(h.c))
    .map((h) => ({
      at: h.c.pos,
      d: [h.c.move[0] * scene.stretch * 0.85, h.c.move[1] * scene.stretch * 0.85] as Pt,
      s2: 2 * (h.c.kind === 'palm' ? 1.1 : 0.6) ** 2,
    }));
  const anchors = scene.hands.filter((h) => isFixed(h.c)).map((h) => h.c.pos);
  return ([x, y]) => {
    let dx = 0;
    let dy = 0;
    for (const p of pulls) {
      let w = Math.exp(-((x - p.at[0]) ** 2 + (y - p.at[1]) ** 2) / p.s2);
      for (const a of anchors) w *= 1 - Math.exp(-((x - a[0]) ** 2 + (y - a[1]) ** 2) / (2 * 0.55 ** 2));
      dx += p.d[0] * w;
      dy += p.d[1] * w;
    }
    return [x + dx, y + dy];
  };
}

// ── Expression model on the illustrated features ─────────────────────────

interface Half {
  browTop: Pt[];
  browBottom: Pt[];
  eyeUpper: Pt[];
  eyeLower: Pt[];
  crease: Pt[];
  ala: Pt[];
  nasolabial: Pt[];
  lipUpper: Pt[];
  lipSeam: Pt[];
  lipLower: Pt[];
  outline: Pt[];
  eyeClose: number;
}

function half(e: Expr, eyeClose: number, affected: boolean, keepEye: boolean): Half {
  const up = (pts: readonly Pt[], dy: number) => pts.map(([x, y]) => [x, y + dy] as Pt);
  const brow = 0.55 * e.brow;
  const close = Math.max(eyeClose, e.eyeClose);
  const narrow = keepEye ? 0 : 0.12 * e.smile + 0.1 * e.snarl;
  // Mouth corner and lip movement (outward = +x on this half).
  const v = e.vowel;
  const vk = e.vowelK;
  const open = v ? { a: 0.95, e: 0.45, i: 0.18, o: 0.6, u: 0.22 }[v] * vk : 0;
  const wide = v ? { a: 0.05, e: 0.3, i: 0.45, o: -0.35, u: -0.55 }[v] * vk : 0;
  const cx = 0.38 * e.smile - 0.55 * e.pucker + wide;
  const cy = 0.45 * e.smile + 0.05 * e.snarl;
  const lipUp = 0.3 * e.snarl + 0.1 * e.smile + 0.12 * e.pucker;
  const lipDown = open + 0.12 * e.pucker;
  const moveLip = (pts: readonly Pt[], ky: number, lower: boolean): Pt[] =>
    pts.map(([x, y]) => {
      const t = Math.max(0, Math.min(1, (x - XM) / (-0.85 - XM))); // 0 midline → 1 corner
      const pucker = e.pucker * (lower ? -0.08 : 0.08) * (1 - t);
      return [x + cx * t, y + cy * t + ky * (1 - t * 0.6) + pucker] as Pt;
    });
  const eyeUpper = FACE.eyeUpper.map(([x, y], i) => {
    const target = FACE.eyeLower[FACE.eyeLower.length - 1 - i]![1];
    return [x, y + (target - y) * 0.94 * close + (1 - close) * brow * 0.25] as Pt;
  });
  const eyeLower = FACE.eyeLower.map(([x, y]) => [x, y + narrow] as Pt);
  const outline = FACE.outline.map(([x, y]) => {
    const w = Math.exp(-((y + 4.2) ** 2) / (2 * 1.1 ** 2));
    return [x + 0.55 * e.puff * w * (x > XM ? 1 : 0), y - open * 0.6 * Math.max(0, (-5 - y) / 3)] as Pt;
  });
  void affected;
  return {
    browTop: up(FACE.browTop, brow),
    browBottom: up(FACE.browBottom, brow),
    eyeUpper,
    eyeLower,
    crease: up(FACE.crease, brow * 0.3 - 0.35 * close),
    ala: up(FACE.ala, 0.35 * e.snarl),
    nasolabial: FACE.nasolabial.map(([x, y], i) => [x + (i === 2 ? cx * 0.4 : 0), y + (i ? cy * 0.35 : 0.3 * e.snarl)] as Pt),
    lipUpper: moveLip(FACE.lipUpper, lipUp, false),
    lipSeam: moveLip(FACE.lipSeam, lipUp * 0.5, false),
    lipLower: moveLip(FACE.lipLower, -lipDown, true),
    outline,
    eyeClose: close,
  };
}

// ── Muscles ──────────────────────────────────────────────────────────────

function muscleSvg(shape: MuscleShape, f: Frame, warp: Warp, act: number, id: string): string {
  const S = (p: Pt) => f.toS(warp(p));
  const band = `fill="#D94848" fill-opacity="${(0.16 + 0.4 * act).toFixed(2)}"`;
  const fibre = `stroke="#b83232" stroke-width="0.9" opacity="${(0.3 + 0.5 * act).toFixed(2)}" fill="none"`;
  if (shape.type === 'ring') {
    const ring = (rx: number, ry: number) =>
      Array.from({ length: 48 }, (_, i) => {
        const a = (i / 48) * 2 * Math.PI;
        return S([shape.c[0] + rx * Math.cos(a), shape.c[1] + ry * Math.sin(a)]);
      });
    const outer = ring(shape.rOut[0], shape.rOut[1]);
    const inner = ring(shape.rIn[0], shape.rIn[1]);
    const fibres = [0.25, 0.5, 0.75]
      .map((k) => smooth(ring(shape.rIn[0] + (shape.rOut[0] - shape.rIn[0]) * k, shape.rIn[1] + (shape.rOut[1] - shape.rIn[1]) * k), true))
      .map((d) => `<path d="${d}" ${fibre}/>`)
      .join('');
    return `<path d="${smooth(outer, true)} ${smooth(inner, true)}" fill-rule="evenodd" ${band}/>${fibres}`;
  }
  if (shape.type === 'strip') {
    const w = shape.width / 2;
    const side = (k: number) =>
      shape.path.map((p, i) => {
        const a = shape.path[Math.max(0, i - 1)]!;
        const b = shape.path[Math.min(shape.path.length - 1, i + 1)]!;
        const dx = b[0] - a[0];
        const dy = b[1] - a[1];
        const l = Math.hypot(dx, dy) || 1;
        return S([p[0] - (dy / l) * w * k, p[1] + (dx / l) * w * k]);
      });
    const left = side(1);
    const right = side(-1).reverse();
    const fibres = [-0.5, 0, 0.5].map((k) => `<path d="${smooth(side(k), false)}" ${fibre}/>`).join('');
    return `<path d="${smooth([...left, ...right], true)}" ${band}/>${fibres}`;
  }
  const poly = shape.poly.map(S);
  const [fx, fy] = shape.fibre;
  const lines: string[] = [];
  const xs = shape.poly.map((p) => p[0]);
  const ys = shape.poly.map((p) => p[1]);
  const cx = (Math.min(...xs) + Math.max(...xs)) / 2;
  const cy = (Math.min(...ys) + Math.max(...ys)) / 2;
  const span = Math.max(Math.max(...xs) - Math.min(...xs), Math.max(...ys) - Math.min(...ys));
  const l = Math.hypot(fx, fy) || 1;
  const [ux, uy] = [fx / l, fy / l];
  for (let k = -span; k <= span; k += 0.35) {
    const o: Pt = [cx - uy * k, cy + ux * k];
    lines.push(
      `<path d="M${S([o[0] - ux * span, o[1] - uy * span])
        .map(f1)
        .join(',')} L${S([o[0] + ux * span, o[1] + uy * span])
        .map(f1)
        .join(',')}" ${fibre}/>`,
    );
  }
  return `<clipPath id="${id}"><path d="${smooth(poly, true)}"/></clipPath><path d="${smooth(poly, true)}" ${band}/><g clip-path="url(#${id})">${lines.join('')}</g>`;
}

// ── Scene ────────────────────────────────────────────────────────────────

export interface Rendered {
  svg: string;
  viewBox: string;
  loupe: { x: number; y: number; r: number } | null;
}

export function render2D(scene: Scene, v: View2D, uid = 'm'): Rendered {
  const f = frame(v);
  const warp = makeWarp(scene);
  const keepEye = scene.keep === 'eye';
  const eyeClose = scene.eyesClosed ? 1 : 0;
  const A = half(scene.expr, eyeClose, true, keepEye);
  const H = half(scene.expr, eyeClose, false, keepEye);
  const S = (p: Pt) => f.toS(warp(p));
  const Sm = (p: Pt) => f.toS(mirrorPt(p)); // healthy half, never deformed

  // Head motion: yaw turns the face towards the healthy side, pitch lifts the chin.
  const yaw = (scene.head.yaw * Math.PI) / 180;
  const pitch = (scene.head.pitch * Math.PI) / 180;
  const pivot: V = f.toS([XM, -7]);
  const headTf = `translate(${f1(-f.s * Math.sin(yaw) * 1.4 * U)} ${f1(-Math.sin(pitch) * 1.3 * U)}) translate(${f1(pivot[0])} ${f1(pivot[1])}) scale(${(1 - 0.28 * Math.abs(Math.sin(yaw))).toFixed(3)} ${(1 - 0.18 * Math.abs(Math.sin(pitch))).toFixed(3)}) translate(${f1(-pivot[0])} ${f1(-pivot[1])})`;

  // Face outline: affected half (deformed) + mirrored healthy half.
  const outline = [...A.outline.map(S), ...[...H.outline].reverse().slice(1, -1).map(Sm)];
  const hair = [...FACE.hair.map(S), ...[...FACE.hair].reverse().slice(1, -1).map(Sm)];

  const eye = (h: Half, P: (p: Pt) => V, affectedEye: boolean) => {
    const almond = [...h.eyeUpper.map(P), ...h.eyeLower.slice(1, -1).map(P)];
    const c = P(FACE.iris.c);
    const id = `${uid}-${affectedEye ? 'ea' : 'eh'}`;
    const lid = smooth(h.eyeUpper.map(P), false);
    return `<clipPath id="${id}"><path d="${smooth(almond, true)}"/></clipPath>
      <path d="${smooth(almond, true)}" fill="#fff"/>
      <g clip-path="url(#${id})"><circle cx="${f1(c[0])}" cy="${f1(c[1])}" r="${0.42 * U}" fill="#6B4E3D"/><circle cx="${f1(c[0])}" cy="${f1(c[1])}" r="${0.2 * U}" fill="#1d1411"/><circle cx="${f1(c[0] + 4)}" cy="${f1(c[1] - 4)}" r="2.6" fill="#fff"/></g>
      <path d="${lid}" fill="none" stroke="#3a2a22" stroke-width="${h.eyeClose > 0.6 ? 3.6 : 3.2}" stroke-linecap="round"/>
      ${h.eyeClose > 0.6 ? `<path d="${lid}" fill="none" stroke="#3a2a22" stroke-width="1.4" stroke-dasharray="1.5 4" transform="translate(0 4)"/>` : ''}
      <path d="${smooth(h.crease.map(P), false)}" fill="none" stroke="#d8a88a" stroke-width="1.3"/>
      <path d="${smooth(h.eyeLower.map(P), false)}" fill="none" stroke="#c99c82" stroke-width="1.4"/>`;
  };
  const brow = (h: Half, P: (p: Pt) => V) => `<path d="${smooth([...h.browTop.map(P), ...h.browBottom.map(P)], true)}" fill="#4a372c"/>`;
  const nose = (h: Half, P: (p: Pt) => V) =>
    `<path d="${smooth(FACE.noseSide.map(P), false)}" fill="none" stroke="#d9a787" stroke-width="2" stroke-linecap="round" opacity="0.7"/>
     <path d="${smooth(h.ala.map(P), false)}" fill="none" stroke="#c98c6e" stroke-width="2.6" stroke-linecap="round"/>
     <ellipse cx="${f1(P(FACE.nostril.c)[0])}" cy="${f1(P(FACE.nostril.c)[1])}" rx="${FACE.nostril.rx * U}" ry="${FACE.nostril.ry * U}" fill="#a86a55" opacity="0.7"/>
     <path d="${smooth(h.nasolabial.map(P), false)}" fill="none" stroke="#d29a7c" stroke-width="${1.6 + 1.6 * (scene.expr.smile + scene.expr.snarl)}" stroke-linecap="round" opacity="${0.45 + 0.4 * (scene.expr.smile + scene.expr.snarl)}"/>`;
  const lipsUpper = [...A.lipUpper.map(S), ...[...H.lipUpper].reverse().slice(1).map(Sm)];
  const lipsLower = [...A.lipLower.map(S), ...[...H.lipLower].reverse().slice(1).map(Sm)];
  const seam = [...A.lipSeam.map(S), ...[...H.lipSeam].reverse().slice(1).map(Sm)];
  const opening = scene.expr.vowel && scene.expr.vowelK > 0.05;
  const mouth = `<path d="${smooth([...lipsUpper, ...[...seam].reverse().slice(1, -1)], true)}" fill="#D98B86"/>
    <path d="${smooth([...lipsLower, ...[...seam].reverse().slice(1, -1)], true)}" fill="#E39A93"/>
    ${
      opening
        ? `<path d="${smooth(
            [
              ...seam,
              ...[...lipsLower]
                .reverse()
                .slice(1, -1)
                .map(([x, y]) => [x, y - 5] as V),
            ],
            true,
          )}" fill="#6B2A2E"/>`
        : ''
    }
    <path d="${smooth(seam, false)}" fill="none" stroke="#b25f59" stroke-width="2.2" stroke-linecap="round"/>`;
  const wrinkles =
    scene.expr.brow > 0.05
      ? [3.0, 3.35, 3.7]
          .map(
            (y, i) =>
              `<path d="${smooth([Sm([-1.2, y]), f.toS([XM, y + 0.12]), S([-1.2, y])], false)}" fill="none" stroke="#c99478" stroke-width="1.3" opacity="${(scene.expr.brow * (0.8 - i * 0.15)).toFixed(2)}"/>`,
          )
          .join('')
      : '';
  const noseWrinkles =
    scene.expr.snarl > 0.05
      ? [0.2, 0.55, 0.9]
          .map(
            (y) =>
              `<path d="${smooth([f.toS([-1.75, y]), f.toS([XM, y + 0.15]), f.toS([2 * XM + 1.75, y])], false)}" fill="none" stroke="#c99478" stroke-width="1.2" opacity="${(scene.expr.snarl * 0.7).toFixed(2)}"/>`,
          )
          .join('')
      : '';

  // Muscle overlay
  const muscle = scene.muscle && v.showMuscle ? MUSCLES[scene.muscle] : null;
  const act =
    scene.mode === 'stretch'
      ? 0.25 + 0.75 * scene.stretch
      : 0.35 +
        0.5 *
          Math.max(
            scene.expr.brow,
            scene.expr.eyeClose,
            scene.expr.smile,
            scene.expr.snarl,
            scene.expr.pucker,
            scene.expr.puff,
            scene.expr.vowelK,
          );
  const muscleSvgs = muscle ? muscle.shapes.map((sh, i) => muscleSvg(sh, f, warp, act, `${uid}-mc${i}`)).join('') : '';
  const muscleLabel = muscle
    ? (() => {
        const [x, y] = f.toS(muscle.label);
        return `<text x="${f1(x)}" y="${f1(y)}" text-anchor="middle" class="fsr-muscle">${muscle.name}</text>`;
      })()
    : '';

  // Hands, marks and callouts
  const pulse = 0.5 + 0.5 * Math.sin(performance.now() / 220);
  const op = Math.min(1, scene.approach * 1.3);
  let targets = '';
  let shadows = '';
  let hands = '';
  let marks = '';
  let skin = '';
  let pads = '';
  const handPts: V[] = [];
  if (scene.mode === 'stretch' && op > 0.01) {
    if (scene.phase.key === 'prepare' || scene.phase.key === 'rest') {
      for (const h of scene.hands) {
        const [x, y] = S(h.c.pos);
        targets += `<circle cx="${f1(x)}" cy="${f1(y)}" r="${h.c.kind === 'palm' ? 30 : 13}" class="fsr-target" stroke="${HAND_COLOR[h.c.hand]}"/>`;
      }
    }
    const byHand: Record<string, Scene['hands']> = {};
    for (const h of scene.hands) (byHand[h.c.hand] ||= []).push(h);
    for (const [letter, list] of Object.entries(byHand)) {
      const color = HAND_COLOR[letter as 'A' | 'B'];
      const padList: (Pad & { c: Contact; rest: V })[] = list.map((h) => {
        const F = f.dir(h.c.from);
        const p0 = f.toS(h.at);
        const off = (1 - scene.approach) * 140;
        return {
          c: h.c,
          F,
          label: h.c.label,
          intraoral: h.c.intraoral,
          hook: h.c.kind === 'hook',
          pos: [p0[0] + F[0] * off, p0[1] + F[1] * off],
          rest: p0,
        };
      });
      for (const p of padList) {
        handPts.push(p.pos);
        if (scene.approach > 0.9 && !p.intraoral) shadows += pressShadow(p.pos, p.F, p.c.kind === 'palm' ? 26 : 11);
        if (!isFixed(p.c)) skin += stretchLines(p.rest, f.dir(p.c.move), scene.stretch, p.c.kind === 'palm' ? 24 : 10);
      }
      const palm = padList.find((p) => p.c.kind === 'palm');
      hands += `<g opacity="${op.toFixed(2)}">`;
      hands += palm
        ? palmHand({ heel: palm.pos, F: palm.F, U, color, thumbSide: f.dir([-1, 0]) })
        : fingerHand({ pads: padList, U, color });
      hands += '</g>';
      for (const p of padList) {
        const c = p.c;
        const [px, py] = p.pos;
        marks += `<g opacity="${op.toFixed(2)}">`;
        if (isFixed(c)) {
          marks += `<circle cx="${f1(px)}" cy="${f1(py)}" r="${f1(15 + pulse * 3)}" fill="none" stroke="${color}" stroke-width="2.5" stroke-dasharray="4 3"/>`;
          // Lock badge above the highest fixed pad, or below the lowest one when "above" would cover the eye.
          const fixed = list.filter((o) => isFixed(o.c));
          const top = fixed.reduce((a, o) => (o.c.pos[1] > a.c.pos[1] ? o : a));
          const bottom = fixed.reduce((a, o) => (o.c.pos[1] < a.c.pos[1] ? o : a));
          const above: Pt = [top.c.pos[0], top.c.pos[1] + 30 / U];
          const overEye = Math.abs(above[0]) < 1.25 && above[1] > -0.6 && above[1] < 0.75;
          if (!overEye && top.c === c) marks += lockBadge(px, py - 30, color);
          if (overEye && bottom.c === c) marks += lockBadge(px, py + 30, color);
        } else if (scene.phase.key !== 'rest') {
          const m = f.dir(c.move);
          let off: V = [0, 0];
          if (Math.abs(p.F[0] * m[0] + p.F[1] * m[1]) > 0.7) {
            let P2: V = [-p.F[1], p.F[0]];
            if (list.length > 1) {
              const cx = list.reduce((a, o) => a + o.c.pos[0], 0) / list.length;
              const cy = list.reduce((a, o) => a + o.c.pos[1], 0) / list.length;
              const d = f.dir([c.pos[0] - cx, c.pos[1] - cy]);
              if (P2[0] * d[0] + P2[1] * d[1] < 0) P2 = [-P2[0], -P2[1]];
            }
            off = [P2[0] * 26, P2[1] * 26];
          }
          const ax = px + m[0] * 20 + off[0];
          const ay = py + m[1] * 20 + off[1];
          const l = 34 + (scene.phase.key === 'stretch' ? pulse * 6 : 0);
          marks += `<line x1="${f1(ax)}" y1="${f1(ay)}" x2="${f1(ax + m[0] * l)}" y2="${f1(ay + m[1] * l)}" stroke="#fff" stroke-width="9" stroke-linecap="round" opacity="0.9"/>`;
          marks += `<line x1="${f1(ax)}" y1="${f1(ay)}" x2="${f1(ax + m[0] * l)}" y2="${f1(ay + m[1] * l)}" stroke="${color}" stroke-width="5" stroke-linecap="round" marker-end="url(#${uid}-arr${c.hand})"/>`;
        }
        marks += '</g>';
      }
    }
    if (v.callouts && op > 0.15) {
      const top = (scene.muscle === 'platysma' || scene.hands.some((h) => h.c.pos[1] < -9) ? -7.2 : -7.4) * U;
      pads = callouts(scene, f, op, v.loupe ? top + 265 : -Infinity);
    }
  }

  // Massage fingertips
  if (scene.mode === 'massage' && scene.stroke) {
    const st = scene.stroke;
    const path = st.path.map((p) => f.toS(p));
    marks += `<path d="${smooth(path, false)}" fill="none" stroke="#fff" stroke-width="9" stroke-linecap="round" opacity="0.8"/>
      <path d="${smooth(path, false)}" fill="none" stroke="${HAND_COLOR.B}" stroke-width="4" stroke-linecap="round" marker-end="url(#${uid}-arrB)"/>`;
    const F = f.dir(st.from);
    const p0 = f.toS(st.at);
    const off = (1 - scene.approach) * 140;
    const pos: V = [p0[0] + F[0] * off, p0[1] + F[1] * off];
    const K: V = [-F[1], F[0]];
    handPts.push(pos);
    hands += `<g opacity="${Math.min(1, scene.approach * 1.3).toFixed(2)}">${fingerHand({
      pads: [
        { pos: [pos[0] + K[0] * 8, pos[1] + K[1] * 8], F, label: '검지' },
        { pos: [pos[0] - K[0] * 8, pos[1] - K[1] * 8], F, label: '중지' },
      ],
      U,
      color: HAND_COLOR.B,
    })}</g>`;
    shadows += pressShadow(pos, F, 14);
  }

  // Keep-still marker (dissociation) and eye-care props
  let props = '';
  if (scene.keep) {
    const c = scene.keep === 'eye' ? S([0, 0.05]) : S([-1.6, -4.95]);
    props += `<ellipse cx="${f1(c[0])}" cy="${f1(c[1])}" rx="${scene.keep === 'eye' ? 1.6 * U : 1.4 * U}" ry="${scene.keep === 'eye' ? 1.1 * U : 0.9 * U}" fill="none" stroke="${HAND_COLOR.A}" stroke-width="3" stroke-dasharray="6 4"/>${lockBadge(c[0] + f.s * 1.5 * U, c[1] - 0.9 * U, HAND_COLOR.A)}
      <text x="${f1(c[0] + f.s * 1.5 * U)}" y="${f1(c[1] - 1.5 * U)}" text-anchor="middle" class="fsr-keep">움직이지 않게</text>`;
  }
  if (scene.mode === 'eyecare') {
    const e = S([0, 0]);
    if (scene.scene === 0) {
      const drop = ((performance.now() / 1300) % 1) * 1.9 * U;
      props += `<g transform="translate(${f1(e[0])} ${f1(e[1] - 3.2 * U)})"><rect x="-12" y="-44" width="24" height="44" rx="8" fill="#fff" stroke="${HAND_COLOR.A}" stroke-width="2.5"/><path d="M-6 0 L6 0 L0 12 Z" fill="${HAND_COLOR.A}"/></g>
        <path transform="translate(${f1(e[0])} ${f1(e[1] - 2.5 * U + drop)})" d="M0 -9 Q7 1 0 6 Q-7 1 0 -9 Z" fill="#6DB3F2" stroke="#fff" stroke-width="1.5"/>`;
    } else if (scene.scene === 1) {
      const a = f.toS([0, 0]);
      const b = f.toS(mirrorPt([0, 0]));
      props += `<g fill="#2B2B2E" fill-opacity="0.88"><rect x="${f1(a[0] - 1.35 * U)}" y="${f1(a[1] - 0.8 * U)}" width="${2.7 * U}" height="${1.6 * U}" rx="16"/><rect x="${f1(b[0] - 1.35 * U)}" y="${f1(b[1] - 0.8 * U)}" width="${2.7 * U}" height="${1.6 * U}" rx="16"/><rect x="${f1(Math.min(a[0], b[0]) + 1.3 * U)}" y="${f1(a[1] - 0.3 * U)}" width="${f1(Math.abs(a[0] - b[0]) - 2.6 * U)}" height="7" rx="3"/></g>`;
    } else if (scene.scene === 2) {
      props += `<ellipse cx="${f1(e[0])}" cy="${f1(e[1])}" rx="${1.5 * U}" ry="${1.15 * U}" fill="#fff" stroke="#c9c9c9" stroke-width="2"/><rect x="${f1(e[0] - 1.7 * U)}" y="${f1(e[1] - 6)}" width="${3.4 * U}" height="12" rx="3" fill="#f2e6d0" transform="rotate(-25 ${f1(e[0])} ${f1(e[1])})"/>`;
    } else {
      props += `<path d="M${f1(e[0] - 22)} ${f1(e[1] - 22)} L${f1(e[0] + 22)} ${f1(e[1] + 22)} M${f1(e[0] + 22)} ${f1(e[1] - 22)} L${f1(e[0] - 22)} ${f1(e[1] + 22)}" stroke="#D03B3B" stroke-width="7" stroke-linecap="round"/>`;
    }
  }
  if (scene.mode === 'breath') {
    const c = f.toS([XM, -1.5]);
    props += `<circle cx="${f1(c[0])}" cy="${f1(c[1])}" r="${f1((7.2 + 0.7 * scene.stretch) * U)}" fill="none" stroke="${HAND_COLOR.A}" stroke-width="${f1(3 + 3 * scene.stretch)}" opacity="${(0.3 + 0.5 * scene.stretch).toFixed(2)}"/>`;
  }

  const neckShown = scene.muscle === 'platysma' || scene.hands.some((h) => h.c.pos[1] < -9);
  const neck = [...FACE.neck.map((p) => f.toS(p)), ...[...FACE.neck].reverse().map((p) => f.toS(mirrorPt(p)))];
  const body = `<path d="${smooth([...FACE.shoulder.map((p) => f.toS(p)), ...[...FACE.shoulder].reverse().map((p) => f.toS(mirrorPt(p)))], false)} Z" fill="#3E5C7E"/>
    <path d="${smooth(neck, true)}" fill="#EDBFA2"/>
    <path d="${smooth(
      FACE.clavicle.map((p) => f.toS(p)),
      false,
    )} M${smooth(
      FACE.clavicle.map((p) => f.toS(mirrorPt(p))),
      false,
    ).slice(1)}" fill="none" stroke="#c98f72" stroke-width="2" opacity="${neckShown ? 0.9 : 0.4}"/>`;

  const ear = (P: (p: Pt) => V, c: Pt) => {
    const e = P(c);
    return `<ellipse cx="${f1(e[0])}" cy="${f1(e[1])}" rx="${FACE.ear.rx * U}" ry="${FACE.ear.ry * U}" fill="#EDBFA2"/>`;
  };

  const head = `<g transform="${headTf}">
      ${ear(S, FACE.ear.c)}${ear(Sm, FACE.ear.c)}
      <path d="${smooth(outline, true)}" fill="url(#${uid}-skin)"/>
      <path d="${smooth(hair, true)}" fill="#3B2F2F"/>
      ${wrinkles}
      <ellipse cx="${f1(S([1.2, -2.3])[0])}" cy="${f1(S([1.2, -2.3])[1] - 12 * scene.expr.smile)}" rx="${0.75 * U}" ry="${0.42 * U}" fill="#f4a9a0" opacity="${(0.25 + 0.15 * scene.expr.smile).toFixed(2)}"/>
      <ellipse cx="${f1(Sm([1.2, -2.3])[0])}" cy="${f1(Sm([1.2, -2.3])[1] - 12 * scene.expr.smile)}" rx="${0.75 * U}" ry="${0.42 * U}" fill="#f4a9a0" opacity="${(0.25 + 0.15 * scene.expr.smile).toFixed(2)}"/>
      ${muscleSvgs}
      ${brow(A, S)}${brow(H, Sm)}
      ${eye(A, S, true)}${eye(H, Sm, false)}
      ${nose(A, S)}${nose(H, Sm)}${noseWrinkles}
      <ellipse cx="${f1(f.toS([XM, -2.6])[0])}" cy="${f1(f.toS([XM, -2.6])[1])}" rx="${0.55 * U}" ry="${0.4 * U}" fill="#eab394" opacity="0.5"/>
      ${mouth}
      <g>${skin}</g>
      ${muscleLabel}
      ${targets}${props}
      <g>${shadows}</g>
      <g opacity="${v.ghostHands ? 0.5 : 1}">${hands}</g>
      ${marks}
    </g>`;

  const svg = `<defs>
      <radialGradient id="${uid}-skin" cx="50%" cy="40%" r="65%"><stop offset="0" stop-color="#FCE5D2"/><stop offset="1" stop-color="#F2CBAE"/></radialGradient>
      <filter id="fsrSoft" x="-50%" y="-50%" width="200%" height="200%"><feGaussianBlur stdDeviation="3.2"/></filter>
      <marker id="${uid}-arrA" viewBox="0 0 10 10" refX="5" refY="5" markerWidth="4" markerHeight="4" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z" fill="${HAND_COLOR.A}"/></marker>
      <marker id="${uid}-arrB" viewBox="0 0 10 10" refX="5" refY="5" markerWidth="4" markerHeight="4" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z" fill="${HAND_COLOR.B}"/></marker>
    </defs>
    ${body}
    <g id="${uid}-scene">${head}</g>
    <g transform="${headTf}">${pads}</g>`;

  // Frame: whole face, extended to the neck when needed; compact thumbnails crop to the action.
  let vb: [number, number, number, number] = neckShown ? [-8.2 * U, -7.2 * U, 16.4 * U, 21 * U] : [-7.6 * U, -7.4 * U, 15.2 * U, 16.6 * U];
  let loupe: Rendered['loupe'] = null;
  if (scene.mode === 'stretch' && scene.hands.length) {
    const pts = scene.hands.map((h) => S(h.c.pos));
    const cx = pts.reduce((a, p) => a + p[0], 0) / pts.length;
    const cy = pts.reduce((a, p) => a + p[1], 0) / pts.length;
    const r = Math.max(2.4 * U, ...pts.map((p) => Math.hypot(p[0] - cx, p[1] - cy) + 1.2 * U));
    loupe = { x: cx, y: cy, r };
    if (v.compact) vb = [cx - r * 1.35, cy - r * 1.35, r * 2.7, r * 2.7];
  } else if (v.compact) vb = [-6.4 * U, -6.6 * U, 12.8 * U, 13.4 * U];
  void handPts;
  return { svg, viewBox: vb.map(f1).join(' '), loupe };
}

/** Callouts naming the action and landmark for each contact group, pushed apart so they never overlap. */
function callouts(scene: Scene, f: Frame, op: number, healthyMinY: number): string {
  const seen = new Set<string>();
  const items: { c: Contact; p: V; t: V; w: number }[] = [];
  for (const h of scene.hands) {
    const c = h.c;
    const key = `${c.hand}|${c.land}|${c.act}`;
    if (seen.has(key)) continue;
    seen.add(key);
    const mates = scene.hands.filter((o) => o.c.hand === c.hand && o.c.land === c.land && o.c.act === c.act);
    const p = mates.reduce<V>(
      (a, o) => {
        const q = f.toS(o.at);
        return [a[0] + q[0] / mates.length, a[1] + q[1] / mates.length];
      },
      [0, 0],
    );
    // Callouts sit in a column outside the face on the side the hand comes from,
    // so the eye/mouth under the fingers stays visible; leader lines connect them.
    const side = Math.abs(c.from[0]) < 0.3 ? 1 : Math.sign(c.from[0]);
    const colX = side > 0 ? 5.2 : 2 * XM - 5.2;
    const w = Math.max(96, 13 * Math.max(c.act.length, c.land.length * 0.85) + 22);
    const cx = f.toS([colX, 0])[0];
    items.push({ c, p, t: [Math.sign(cx) * (7.45 * U - w / 2), p[1]], w });
  }
  // Stack each column top-down without overlap (boxes are 38 px high), keeping the order of the contacts.
  for (const sign of [1, -1]) {
    const col = items.filter((i) => Math.sign(i.t[0]) === sign).sort((a, b) => a.t[1] - b.t[1]);
    const minY = sign === -f.s ? healthyMinY : -Infinity;
    let prev = -Infinity;
    for (const it of col) {
      it.t = [it.t[0], Math.max(it.t[1], prev + 44, minY)];
      prev = it.t[1];
    }
  }
  let out = '';
  for (const { c, p, t, w } of items) {
    const fixed = isFixed(c);
    const color = HAND_COLOR[c.hand];
    const rx = c.kind === 'palm' ? 28 : 16;
    const ry = c.kind === 'palm' ? 20 : 11;
    const F = f.dir(c.from);
    const angle = (Math.atan2(F[1], F[0]) * 180) / Math.PI;
    out += `<g class="fsr-pad" opacity="${op.toFixed(2)}">
      <ellipse cx="${f1(p[0])}" cy="${f1(p[1])}" rx="${rx}" ry="${ry}" transform="rotate(${f1(angle)} ${f1(p[0])} ${f1(p[1])})" fill="${fixed ? 'rgba(47,128,237,0.22)' : 'rgba(242,153,74,0.28)'}" stroke="${color}" stroke-width="2"/>
      <path d="M${f1(p[0])} ${f1(p[1])} L${f1(t[0] + (t[0] > p[0] ? -w / 2 : w / 2))} ${f1(t[1])}" fill="none" stroke="${color}" stroke-width="1.6" stroke-dasharray="4 3"/>
      <g transform="translate(${f1(t[0])},${f1(t[1])})">
        <rect x="${f1(-w / 2)}" y="-19" width="${f1(w)}" height="38" rx="9" fill="#fff" stroke="${color}" stroke-width="1.8"/>
        <text x="0" y="-2" text-anchor="middle" class="fsr-act" fill="${color}">${c.act}</text>
        <text x="0" y="13" text-anchor="middle" class="fsr-land">${c.land}</text>
      </g>
    </g>`;
  }
  return out;
}
