/**
 * Exercise motion: one clock → one scene state, consumed identically by the
 * 2D illustration, the 3D avatar, voice cues and step highlighting. Pure.
 */
import type { Exercise } from './exercises';
import type { MuscleId, Pt } from './face';
import { STRETCHES, contactAt, type Contact, type StretchProgram, type StretchStep } from './stretches';

export type PhaseKey = 'prepare' | 'stretch' | 'hold' | 'release' | 'rest' | 'inhale' | 'exhale' | 'stroke' | 'show';

export interface Phase {
  key: PhaseKey;
  label: string;
  dur: number;
}

export interface Expr {
  brow: number;
  eyeClose: number;
  smile: number;
  snarl: number;
  pucker: number;
  puff: number;
  /** Mouth vowel shape (oral–ocular synkinesis drill), with its intensity in `vowelK`. */
  vowel: 'a' | 'e' | 'i' | 'o' | 'u' | null;
  vowelK: number;
}

export const NEUTRAL: Expr = { brow: 0, eyeClose: 0, smile: 0, snarl: 0, pucker: 0, puff: 0, vowel: null, vowelK: 0 };

export interface Placement {
  c: Contact;
  /** Current contact point (ELC). */
  at: Pt;
}

export interface Scene {
  exerciseId: string;
  mode: 'stretch' | 'expression' | 'massage' | 'breath' | 'eyecare';
  phase: Phase;
  phaseT: number;
  remaining: number;
  /** 1-based repetition within the current step (0 before start). */
  rep: number;
  reps: number;
  stepIndex: number;
  steps: number;
  progress: number;
  done: boolean;
  /** 0..1 stretch amount (hands move, skin stretches). */
  stretch: number;
  /** 0..1 hands arriving at the face. */
  approach: number;
  step: StretchStep | null;
  hands: Placement[];
  muscle: MuscleId | null;
  eyesClosed: boolean;
  head: { yaw: number; pitch: number };
  expr: Expr;
  /** Region that must stay still (dissociation drills). */
  keep: 'eye' | 'mouth' | null;
  /** Massage: current stroke and fingertip position. */
  stroke: { index: number; count: number; path: Pt[]; at: Pt; from: Pt } | null;
  /** Eye-care scene index. */
  scene: number;
  /** Text step of the exercise card to highlight. */
  textStep: number;
}

