export const programFor = (id: string): StretchProgram | undefined =>
  STRETCHES.find((s) => s.id === id) ?? EXTRA_STRETCHES.find((s) => s.id === id);

export const smooth = (t: number) => t * t * (3 - 2 * t);

// ── Timeline ──────────────────────────────────────────────────────────────

interface Block {
  step: number;
  rep: number;
  phase: Phase;
  start: number;
}

export interface Plan {
  blocks: Block[];
  total: number;
  reps: number;
  steps: number;
}

export interface MotionOptions {
  /** Hold time for stretches (s); defaults to the exercise's holdSec. */
  holdSec?: number;
  /** Repetitions per stretch step; defaults to the exercise's reps. */
  reps?: number;
}

export function planFor(ex: Exercise, opt: MotionOptions = {}): Plan {
  const blocks: Block[] = [];
  let t = 0;
  const push = (step: number, rep: number, key: PhaseKey, label: string, dur: number) => {
    blocks.push({ step, rep, phase: { key, label, dur }, start: t });
    t += dur;
  };
  const program = programFor(ex.id);
  let reps = 1;
  let steps = 1;
  if (program) {
    const hold = opt.holdSec ?? ex.holdSec ?? 10;
    reps = opt.reps ?? ex.reps ?? 2;
    steps = program.steps.length;
    program.steps.forEach((_, s) => {
      for (let r = 1; r <= reps; r++) {
        push(s, r, 'prepare', r === 1 ? '손 위치 잡기' : '손 다시 대기', r === 1 ? 4 : 1.5);
        push(s, r, 'stretch', '천천히 늘리기', 2.5);
        push(s, r, 'hold', '늘린 채 유지', hold);
        push(s, r, 'release', '천천히 풀기', 2.5);
        push(s, r, 'rest', '쉬기', 3);
      }
    });
  } else if (EXPRESSION[ex.id]) {
    const hold = opt.holdSec ?? ex.holdSec ?? 3;
    reps = opt.reps ?? ex.reps ?? 5;
    const slow = ex.id === 'dissoc-eye-mouth' ? 3 : 1.5;
    push(0, 0, 'prepare', '준비', 3);
    for (let r = 1; r <= reps; r++) {
      push(0, r, 'stretch', '천천히 움직이기', slow);
      push(0, r, 'hold', '유지', hold);
      push(0, r, 'release', '천천히 풀기', slow);
      push(0, r, 'rest', '쉬기', 2);
    }
  } else if (MASSAGE[ex.id]) {
    push(0, 0, 'prepare', '손가락 대기', 3);
    push(0, 1, 'stroke', '작은 원을 그리며 이동', ex.durationSec);
  } else if (ex.kind === 'relax') {
    reps = Math.max(1, Math.round(ex.durationSec / 10));
    for (let r = 1; r <= reps; r++) {
      push(0, r, 'inhale', '코로 들이마시기', 4);
      push(0, r, 'exhale', '입으로 길게 내쉬기', 6);
    }
  } else {
    reps = ex.steps.length;
    const d = Math.max(8, ex.durationSec / Math.max(1, reps));
    for (let r = 1; r <= reps; r++) push(r - 1, r, 'show', '따라 읽기', d);
  }
  return { blocks, total: t, reps, steps };
}

function amount(key: PhaseKey, t: number): number {
  if (key === 'stretch' || key === 'inhale') return smooth(t);
  if (key === 'hold' || key === 'stroke') return 1;
  if (key === 'release' || key === 'exhale') return 1 - smooth(t);
  return 0;
}

function pointOnPath(path: readonly Pt[], u: number): Pt {
  if (path.length === 1) return path[0]!;
  const seg = path.slice(1).map((b, i) => Math.hypot(b[0] - path[i]![0], b[1] - path[i]![1]));
  let d = Math.max(0, Math.min(1, u)) * seg.reduce((s, x) => s + x, 0);
  for (let i = 0; i < seg.length; i++) {
    if (d <= seg[i]! || i === seg.length - 1) {
      const k = seg[i] ? d / seg[i]! : 0;
      const a = path[i]!;
      const b = path[i + 1]!;
      return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k];
    }
    d -= seg[i]!;
  }
  return path[path.length - 1]!;
}

export function sceneAt(ex: Exercise, elapsed: number, plan: Plan = planFor(ex)): Scene {
  const t = Math.max(0, Math.min(elapsed, plan.total));
  const done = elapsed >= plan.total;
  let i = plan.blocks.findIndex((b) => t < b.start + b.phase.dur);
  if (i < 0) i = plan.blocks.length - 1;
  const b = plan.blocks[i]!;
  const phaseT = Math.min(1, (t - b.start) / b.phase.dur);
  const k = done ? 0 : amount(b.phase.key, phaseT);
  const program = programFor(ex.id);
  const base: Scene = {
    exerciseId: ex.id,
    mode: 'eyecare',
    phase: b.phase,
    phaseT,
    remaining: Math.max(0, b.start + b.phase.dur - t),
    rep: b.rep,
    reps: plan.reps,
    stepIndex: b.step,
    steps: plan.steps,
    progress: plan.total ? t / plan.total : 1,
    done,
    stretch: k,
    approach: 1,
    step: null,
    hands: [],
    muscle: null,
    eyesClosed: false,
    head: { yaw: 0, pitch: 0 },
    expr: { ...NEUTRAL },
    keep: null,
    stroke: null,
    scene: 0,
    textStep: 0,
  };

  if (program) {
    const step = program.steps[b.step]!;
    const first = b.rep === 1;
    const approach =
      b.phase.key === 'prepare' && first
        ? smooth(Math.min(1, phaseT * 1.6))
        : b.phase.key === 'rest' && b.rep === plan.reps
          ? 1 - smooth(phaseT)
          : 1;
    const lastText = ex.steps.length - 1;
    return {
      ...base,
      mode: 'stretch',
      step,
      approach: done ? 0 : approach,
      hands: step.contacts.map((c) => ({ c, at: contactAt(c, k) })),
      muscle: step.muscle,
      eyesClosed: !!step.eyesClosed,
      // A finger inside the mouth needs the lips parted: shown as a slight "아" while the hand is in place.
      expr: step.contacts.some((c) => c.intraoral) ? { ...NEUTRAL, vowel: 'a', vowelK: 0.42 * (done ? 0 : approach) } : { ...NEUTRAL },
      head: { yaw: (step.head?.yaw ?? 0) * k, pitch: (step.head?.pitch ?? 0) * k },
      textStep:
        program.steps.length > 1
          ? Math.min(lastText, b.step)
          : b.phase.key === 'prepare'
            ? 0
            : b.phase.key === 'stretch'
              ? Math.min(lastText, 1)
              : b.phase.key === 'hold'
                ? Math.min(lastText, 2)
                : lastText,
    };
  }
  const es = EXPRESSION[ex.id];
  if (es) {
    return {
      ...base,
      mode: 'expression',
      expr: { ...NEUTRAL, ...es.expr(k, b.rep) },
      keep: es.keep ?? null,
      muscle: es.muscle,
      textStep:
        b.phase.key === 'prepare' ? 0 : b.phase.key === 'stretch' ? 1 : b.phase.key === 'hold' ? 2 : Math.min(3, ex.steps.length - 1),
    };
  }
  const ms = MASSAGE[ex.id];
  if (ms) {
    const n = ms.strokes.length;
    const u = b.phase.key === 'stroke' ? phaseT : 0;
    const idx = Math.min(n - 1, Math.floor(u * n));
    const local = b.phase.key === 'stroke' ? u * n - idx : 0;
    const st = ms.strokes[idx]!;
    const p = pointOnPath(st.path, local);
    const r = b.phase.key === 'stroke' && !done ? 0.14 : 0;
    const ang = (t / 1.1) * 2 * Math.PI;
    return {
      ...base,
      mode: 'massage',
      approach: b.phase.key === 'prepare' ? smooth(Math.min(1, phaseT * 1.6)) : done ? 0 : 1,
      muscle: ms.muscle,
      eyesClosed: !!ms.eyesClosed,
      stroke: { index: idx, count: n, path: st.path, at: [p[0] + r * Math.cos(ang), p[1] + r * Math.sin(ang)], from: st.from },
      textStep: Math.min(ex.steps.length - 1, Math.floor(base.progress * ex.steps.length)),
    };
  }
  if (ex.kind === 'relax') {
    return {
      ...base,
      mode: 'breath',
      eyesClosed: true,
      textStep: Math.min(ex.steps.length - 1, Math.floor(base.progress * ex.steps.length)),
    };
  }
  return { ...base, mode: 'eyecare', scene: Math.min(3, b.step), textStep: Math.min(ex.steps.length - 1, b.step) };
}

export const hasMotion = (ex: Exercise) =>
  !!(programFor(ex.id) || EXPRESSION[ex.id] || MASSAGE[ex.id] || ex.kind === 'relax' || ex.kind === 'eyecare');
